    bones_radius_tooltip = "This bone's gizmo sphere size in the 3D view. Also used as the\nreach for Rigid Bind's Proximity mode, and as the envelope-binding\nradius when exporting to FBX without real per-vertex weights --\na bone spanning a wide/long area may need a bigger radius.",
    bones_length_label = "Length",
    bones_length_tooltip = "How far this bone extends along its own local Y axis\n(head-to-tail, in Blender terms). For a real Blender-imported\nbone this is the actual authored length; Recompute sets it to\nthe real geometric distance to this bone's child (or continues\nfrom its parent for a leaf) when there's no real data.",
    bones_length_zero_warning = "Length is 0 -- this bone's rotation is ignored on FBX export;\na direction gets guessed from position instead, which is often\nwrong for a hand-added bone. Use Recompute to derive a real\nlength/orientation.",
    bones_roll_label = "Roll",
    bones_roll_tooltip = "Twist around this bone's own aim direction (its local Y axis) --\nchanging it never moves the bone or its child, only rotates the\nmesh's weighted vertices around that axis. The angle is relative\nto a deterministic reference, not an absolute world angle, so 0\ndoesn't mean \"untwisted\" for every bone. Check this bone's\nHighlight box to see a cyan rod showing which way Roll points.",
    bones_recompute_button = "Recompute",
    bones_recompute_tooltip = "Aims this bone at its child (or continues the direction from\nits parent) and sets Length from that distance -- the same\nfallback FBX export already uses silently when Length is 0, now\nbaked into real, editable data. Roll is preserved (kept relative\nto the new aim), never reset.",
    bones_recompute_all_button = "Recompute All",
    bones_recompute_all_tooltip = "Runs Recompute (see Bones table) on every bone whose Length is\n0 in one click -- bones that already have real orientation data\n(e.g. from a Blender import) are left untouched.",
    bones_recompute_all_force_checkbox = "even if Length is already set",
    bones_recompute_all_force_tooltip = "Recompute All also processes bones that already have a nonzero\nLength -- useful after applying a borrowed/Mixamo armature\ntemplate and then manually dragging joints to fit this specific\nmesh, since repositioning a joint never updates its Length on its\nown. Roll is still preserved either way, so this never resets a\nbone's twist.",
