    mixamo_guide_menu = "Get Animated Mesh (Mixamo)...",
    mixamo_guide_title = "Get an Animated Mesh from Mixamo",
    mixamo_guide_intro = "Most downloaded 3D models ship in a T-pose with a rig but no animation - the animation is kept separate on purpose. Mixamo (free, by Adobe) can rig your mesh and apply a ready-made animation (walking, running, etc.) without needing Blender.",
    mixamo_guide_step1 = "1. Get a T-pose mesh (FBX or OBJ). It's fine if it already has a rig/skeleton from the source site.",
    mixamo_guide_step2 = "2. Go to mixamo.com (free Adobe account) and use 'Upload Character' to upload the mesh.",
    mixamo_guide_step3 = "3. Mark the chin, wrists, elbows, knees and groin on the T-pose, then click 'Rig'. Mixamo builds its own skeleton over the mesh - any old bones from the source file are ignored.",
    mixamo_guide_step4 = "4. Browse the animation library, pick a clip (e.g. 'Walking'), and adjust its parameters if needed.",
    mixamo_guide_step5 = "5. Download the character 'With Skin' as FBX - this bakes the animation into the file.",
    mixamo_guide_step6 = "6. Back here, use File > Import via Blender... to bring in that FBX and bake the animation into frames.",
    mixamo_guide_note = "Note: if Mixamo's uploader rejects the mesh (multiple mesh parts, or the existing rig conflicts), open it once in Blender, join all mesh parts into one object and delete the old armature, then re-upload.",
