    bones_radius_tooltip = "O tamanho da esfera deste osso na visualizacao 3D. Tambem usado\ncomo alcance do modo Proximidade do Rigid Bind, e como raio de\nligacao por envelope ao exportar para FBX sem pesos reais por\nvertice -- um osso que cobre uma area larga/longa pode precisar\nde um raio maior.",
    bones_length_label = "Comprimento",
    bones_length_tooltip = "A extensao deste osso ao longo do seu proprio eixo Y local\n(cabeca-a-cauda, em termos do Blender). Para um osso realmente\nimportado do Blender, esse e o comprimento real autoral; Recalcular\ndefine-o como a distancia geometrica real ate o filho deste osso\n(ou continua a partir do pai, se for uma folha) quando nao ha\ndados reais.",
    bones_length_zero_warning = "Comprimento e 0 -- a rotacao deste osso e ignorada na exportacao\npara FBX; uma direcao e adivinhada a partir da posicao, o que\ncostuma ser errado para um osso adicionado manualmente. Use\nRecalcular para obter um comprimento/orientacao real.",
    bones_roll_label = "Rotacao Longitudinal",
    bones_roll_tooltip = "Torcao ao redor da direcao para a qual este osso aponta (seu\neixo Y local) -- alterar isso nunca move o osso ou seu filho, so\nrotaciona os vertices ponderados da malha ao redor desse eixo. O\nangulo e relativo a uma referencia deterministica, nao a um\nangulo absoluto do mundo, entao 0 nao significa \"sem torcao\" para\ntodo osso. Marque a caixa Destacar deste osso para ver uma haste\nciano mostrando para onde a Rotacao Longitudinal aponta.",
    bones_recompute_button = "Recalcular",
