    bones_recompute_all_button = "Recalcular Todos",
    bones_recompute_all_tooltip = "Executa Recalcular (veja a tabela de Ossos) em todo osso com\nComprimento 0, de uma vez -- ossos que ja tem dados reais de\norientacao (ex: de uma importacao do Blender) nao sao alterados.",
    bones_recompute_all_force_checkbox = "mesmo com Comprimento ja definido",
    bones_recompute_all_force_tooltip = "Recalcular Todos tambem processa ossos que ja tem um Comprimento\ndiferente de zero -- util depois de aplicar um armature\nemprestado/do Mixamo e entao arrastar manualmente as juntas para\nencaixar nesta malha especifica, ja que reposicionar uma junta\nnunca atualiza seu Comprimento sozinho. A Rotacao Longitudinal\ncontinua sendo preservada de qualquer forma, entao isso nunca\nreinicia a torcao de um osso.",
