    mixamo_guide_menu = "Obter Mesh Animada (Mixamo)...",
    mixamo_guide_title = "Obter uma Mesh Animada do Mixamo",
    mixamo_guide_intro = "A maioria dos modelos 3D baixados vem em T-pose, com um rig mas sem animação - a animação é mantida separada de propósito. O Mixamo (gratuito, da Adobe) pode fazer o rig da sua mesh e aplicar uma animação pronta (andar, correr, etc.) sem precisar do Blender.",
    mixamo_guide_step1 = "1. Consiga uma mesh em T-pose (FBX ou OBJ). Não tem problema se ela já vier com um rig/esqueleto do site de origem.",
    mixamo_guide_step2 = "2. Acesse mixamo.com (conta Adobe gratuita) e use 'Upload Character' para enviar a mesh.",
    mixamo_guide_step3 = "3. Marque o queixo, pulsos, cotovelos, joelhos e a virilha na T-pose, depois clique em 'Rig'. O Mixamo cria seu próprio esqueleto sobre a mesh - os ossos antigos do arquivo de origem são ignorados.",
    mixamo_guide_step4 = "4. Navegue pela biblioteca de animações, escolha um clipe (ex: 'Walking') e ajuste os parâmetros se necessário.",
    mixamo_guide_step5 = "5. Baixe o personagem 'With Skin' em FBX - isso grava a animação no arquivo.",
    mixamo_guide_step6 = "6. Aqui no editor, use Arquivo > Importar via Blender... para trazer esse FBX e converter a animação em frames.",
    mixamo_guide_note = "Observação: se o Mixamo recusar a mesh (várias partes de mesh, ou conflito com o rig existente), abra-a uma vez no Blender, junte todas as partes em um único objeto e apague o armature antigo antes de enviar novamente.",
